public static void onLivingUpdateEvent(LivingUpdateEvent event){
	// Disables entities' AI when under the effects of paralysis and re-enables it on the last update of the effect
	// - this can't be in the potion class because it requires access to the duration and hence the actual
	// PotionEffect instance
	if(event.getEntity() instanceof EntityLiving && event.getEntityLiving().isPotionActive(WizardryPotions.paralysis)){
		int timeLeft = event.getEntityLiving().getActivePotionEffect(WizardryPotions.paralysis).getDuration();
		((EntityLiving)event.getEntity()).setNoAI(timeLeft > 1);
	}
}

public static void onLivingHurtEvent(LivingHurtEvent event){
	// Paralysed creatures snap out of paralysis when they take critical damage
	if(event.getEntityLiving().isPotionActive(WizardryPotions.paralysis) && event.getEntityLiving().getHealth()
			- event.getAmount() <= Spells.paralysis.getProperty(CRITICAL_HEALTH).floatValue()){
		event.getEntityLiving().removePotionEffect(WizardryPotions.paralysis);
	}
}

public boolean cast(World world, EntityPlayer caster, EnumHand hand, int ticksInUse, SpellModifiers modifiers){

	Vec3d look = caster.getLookVec();
	Vec3d origin = new Vec3d(caster.posX, caster.posY + caster.getEyeHeight() - Y_OFFSET, caster.posZ);
	if(!this.isContinuous && world.isRemote && !Wizardry.proxy.isFirstPerson(caster)){
		origin = origin.add(look.scale(1.2));
	}

	if(!shootSpell(world, origin, look, caster, ticksInUse, modifiers)) return false;

	if(casterSwingsArm(world, caster, hand, ticksInUse, modifiers)) caster.swingArm(hand);
	this.playSound(world, caster, ticksInUse, -1, modifiers);
	return true;
}

protected boolean shootSpell(World world, Vec3d origin, Vec3d direction, @Nullable EntityLivingBase caster, int ticksInUse, SpellModifiers modifiers){

	double range = getRange(world, origin, direction, caster, ticksInUse, modifiers);
	Vec3d endpoint = origin.add(direction.scale(range));

	// Change the filter depending on whether living entities are ignored or not
	RayTraceResult rayTrace = RayTracer.rayTrace(world, origin, endpoint, aimAssist, hitLiquids,
			ignoreUncollidables, false, Entity.class, ignoreLivingEntities ? EntityUtils::isLiving
			: RayTracer.ignoreEntityFilter(caster));

	boolean flag = false;

	if(rayTrace != null){
		// Doesn't matter which way round these are, they're mutually exclusive
		if(rayTrace.typeOfHit == RayTraceResult.Type.ENTITY){
			// Do whatever the spell does when it hits an entity
			// FIXME: Some spells (e.g. lightning web) seem to not render when aimed at item frames
			flag = onEntityHit(world, rayTrace.entityHit, rayTrace.hitVec, caster, origin, ticksInUse, modifiers);
			// If the spell succeeded, clip the particles to the correct distance so they don't go through the entity
			if(flag) range = origin.distanceTo(rayTrace.hitVec);

		}else if(rayTrace.typeOfHit == RayTraceResult.Type.BLOCK){
			// Do whatever the spell does when it hits an block
			flag = onBlockHit(world, rayTrace.getBlockPos(), rayTrace.sideHit, rayTrace.hitVec, caster, origin, ticksInUse, modifiers);
			// Clip the particles to the correct distance so they don't go through the block
			// Unlike with entities, this is done regardless of whether the spell succeeded, since no spells go
			// through blocks (and in fact, even the ray tracer itself doesn't do that)
			range = origin.distanceTo(rayTrace.hitVec);
		}
	}

	// If flag is false, either the spell missed or the relevant entity/block hit method returned false
	if(!flag && !onMiss(world, caster, origin, direction, ticksInUse, modifiers)) return false;

	// Particle spawning
	if(world.isRemote){
		spawnParticleRay(world, origin, direction, caster, range);
	}

	return true;
}

protected boolean onEntityHit(World world, Entity target, Vec3d hit, EntityLivingBase caster, Vec3d origin, int ticksInUse, SpellModifiers modifiers){

	if(EntityUtils.isLiving(target)){

		if(world.isRemote){
			// Rather neatly, the entity can be set here and if it's null nothing will happen.
			ParticleBuilder.create(Type.BEAM).entity(caster).clr(0.2f, 0.6f, 1)
			.pos(caster != null ? origin.subtract(caster.getPositionVector()) : origin).target(target).spawn(world);
			ParticleBuilder.create(Type.LIGHTNING).entity(caster)
			.pos(caster != null ? origin.subtract(caster.getPositionVector()) : origin).target(target).spawn(world);
		}

		// This is a lot neater than it was, thanks to the damage type system.
		if(MagicDamage.isEntityImmune(DamageType.SHOCK, target)){
			if(!world.isRemote && caster instanceof EntityPlayer) ((EntityPlayer)caster).sendStatusMessage(
					new TextComponentTranslation("spell.resist",
					target.getName(), this.getNameForTranslationFormatted()), true);
		}else{
			target.attackEntityFrom(MagicDamage.causeDirectMagicDamage(caster, DamageType.SHOCK),
					getProperty(DAMAGE).floatValue() * modifiers.get(SpellModifiers.POTENCY));
		}

		float durationMultiplier = target instanceof EntityPlayer ? modifiers.get(PLAYER_EFFECT_DURATION_MULTIPLIER) : 1.0f;
		if(!world.isRemote){
			((EntityLivingBase)target).addPotionEffect(new PotionEffect(WizardryPotions.paralysis,
					(int)(getProperty(EFFECT_DURATION).floatValue() * durationMultiplier * modifiers.get(WizardryItems.duration_upgrade)), 0));
		}
	}

	return false;
}

protected boolean onMiss(World world, EntityLivingBase caster, Vec3d origin, Vec3d direction, int ticksInUse, SpellModifiers modifiers){
	// This is first because we want the endpoint to be unaffected by the offset
	Vec3d endpoint = origin.add(direction.scale(getProperty(RANGE).floatValue() * modifiers.get(WizardryItems.range_upgrade)));

	if(world.isRemote){
		ParticleBuilder.create(Type.LIGHTNING).time(4).pos(origin).target(endpoint).scale(0.5f).spawn(world);
		ParticleBuilder.create(Type.BEAM).clr(0.2f, 0.6f, 1).time(4).pos(origin)
		.target(endpoint).spawn(world);
	}

	return true;
}

protected boolean onBlockHit(World world, BlockPos pos, EnumFacing side, Vec3d hit, EntityLivingBase caster, Vec3d origin, int ticksInUse, SpellModifiers modifiers){

	if(world.isRemote){

		if(world.getBlockState(pos).getMaterial().isSolid()){
			Vec3d vec = hit.add(new Vec3d(side.getDirectionVec()).scale(GeometryUtils.ANTI_Z_FIGHTING_OFFSET));
			ParticleBuilder.create(Type.SCORCH).pos(vec).face(side).clr(0.4f, 0.8f, 1).spawn(world);
		}
	}

	return false;
}

