public boolean isValidTarget(Entity target){
	return AllyDesignationSystem.isValidTarget(this.getCaster(), target);
}

	public static boolean isValidTarget(Entity attacker, Entity target){

		// Owned entities inherit their owner's allies
		if(attacker instanceof IEntityOwnable && !isValidTarget(((IEntityOwnable)attacker).getOwner(), target)) return false;

		// Always return false if the target is null
		if(target == null) return false;

		// Always return true if the attacker is null - this must be after the target null check!
		if(attacker == null) return true;

		// Teammates are allies
		if(attacker.isOnSameTeam(target)) return false;

		// Tests whether the target is the attacker
		if(target == attacker) return false;

		// I really shouldn't need to do this, but fake players seem to break stuff...
		if(target instanceof FakePlayer) return false;

		// Use a positive check for these rather than a negative check for monsters, because we only want mobs
		// that are definitely passive
		if(Wizardry.settings.passiveMobsAreAllies && (target.isCreatureType(EnumCreatureType.AMBIENT, false)
				|| target.isCreatureType(EnumCreatureType.CREATURE, false)
				|| target.isCreatureType(EnumCreatureType.WATER_CREATURE, false))){
			return false;
		}

		// Tests whether the target is a creature that was summoned by the attacker
//		if(target instanceof ISummonedCreature && ((ISummonedCreature)target).getCaster() == attacker){
//			return false;
//		}

		// Tests whether the target is a creature that was summoned/tamed (or is otherwise owned) by the attacker
		if(target instanceof IEntityOwnable && ((IEntityOwnable)target).getOwner() == attacker){
			return false;
		}

		// Tests whether the target is a creature that was summoned/tamed (or is otherwise owned) by the attacker
		if(target instanceof IEntityOwnable && attacker instanceof EntityLiving && !(((EntityLiving)attacker).getRevengeTarget() == ((IEntityOwnable)target).getOwner() || ((EntityLiving)attacker).getAttackTarget() == ((IEntityOwnable)target).getOwner())){
			return false;
		}

		// Tests whether the target is a creature that was mind controlled by the attacker
		if(target instanceof EntityLiving && ((EntityLivingBase)target).isPotionActive(WizardryPotions.mind_control)){

			NBTTagCompound entityNBT = target.getEntityData();

			if(entityNBT != null && entityNBT.hasUniqueId(MindControl.NBT_KEY)){
				if(attacker == EntityUtils.getEntityByUUID(target.world,
						entityNBT.getUniqueId(MindControl.NBT_KEY))){
					return false;
				}
			}
		}

		// Ally section
		if(attacker instanceof EntityPlayer && WizardData.get((EntityPlayer)attacker) != null){

			if(target instanceof EntityPlayer){
				// Tests whether the target is an ally of the attacker
				if(WizardData.get((EntityPlayer)attacker).isPlayerAlly((EntityPlayer)target)){
					return false;
				}

//			}else if(target instanceof ISummonedCreature){
//				// Tests whether the target is a creature that was summoned by an ally of the attacker
//				if(((ISummonedCreature)target).getCaster() instanceof EntityPlayer && WizardData.get((EntityPlayer)attacker)
//								.isPlayerAlly((EntityPlayer)((ISummonedCreature)target).getCaster())){
//					return false;
//				}

			}else if(target instanceof IEntityOwnable){
				// Tests whether the target is a creature that was summoned/tamed by an ally of the attacker
				if(isOwnerAlly((EntityPlayer)attacker, (IEntityOwnable)target)) return false;

			}else if(target instanceof EntityLiving && ((EntityLivingBase)target).isPotionActive(WizardryPotions.mind_control)){
				// Tests whether the target is a creature that was mind controlled by an ally of the attacker
				NBTTagCompound entityNBT = target.getEntityData();

				if(entityNBT != null && entityNBT.hasKey(MindControl.NBT_KEY)){

					Entity controller = EntityUtils.getEntityByUUID(target.world, entityNBT.getUniqueId(MindControl.NBT_KEY));

					if(controller instanceof EntityPlayer && WizardData.get((EntityPlayer)attacker).isPlayerAlly((EntityPlayer)controller)){
						return false;
					}
				}
			}
		}

		// Addon predicate registry — only evaluated at the root of the ownership recursion (i.e. when the attacker is
		// not itself an IEntityOwnable). Owned attackers already delegate upward via the recursive call at the top of
		// this method, so skipping them here ensures each logical query fires the predicates exactly once.
		if(!validTargetPredicates.isEmpty() && !(attacker instanceof IEntityOwnable)){
			for(BiPredicate<Entity, Entity> predicate : validTargetPredicates){
				if(predicate.test(attacker, target)) return false;
			}
		}

		return true;
	}

public static void undoGravity(Entity entity){
	if(!entity.hasNoGravity()){
		double gravity = 0.04;
		if(entity instanceof EntityThrowable) gravity = 0.03;
		else if(entity instanceof EntityArrow) gravity = 0.05;
		else if(entity instanceof EntityLivingBase) gravity = 0.08;
		entity.motionY += gravity;
	}
}

public static <T extends Entity> List<T> getEntitiesWithinRadius(double radius, double x, double y, double z, World world, Class<T> entityType){
	AxisAlignedBB aabb = new AxisAlignedBB(x - radius, y - radius, z - radius, x + radius, y + radius, z + radius);
	List<T> entityList = world.getEntitiesWithinAABB(entityType, aabb);
	for(int i = 0; i < entityList.size(); i++){
		if(entityList.get(i).getDistance(x, y, z) > radius){
			entityList.remove(i);
			break;
		}
	}
	return entityList;
}

public boolean cast(World world, EntityPlayer caster, EnumHand hand, int ticksInUse, SpellModifiers modifiers){

	double range = getProperty(RANGE).doubleValue() * modifiers.get(WizardryItems.range_upgrade);
	RayTraceResult rayTrace = RayTracer.standardBlockRayTrace(world, caster, range, hitLiquids, ignoreUncollidables, false);

	if(rayTrace != null && rayTrace.typeOfHit == RayTraceResult.Type.BLOCK && (rayTrace.sideHit == EnumFacing.UP ||
			!requiresFloor)){

		if(!world.isRemote){

			double x = rayTrace.hitVec.x;
			double y = rayTrace.hitVec.y;
			double z = rayTrace.hitVec.z;

			if(!spawnConstruct(world, x, y, z, rayTrace.sideHit, caster, modifiers)) return false;
		}

	}else if(!requiresFloor){

		if(!world.isRemote){

			Vec3d look = caster.getLookVec();

			double x = caster.posX + look.x * range;
			double y = caster.posY + caster.getEyeHeight() + look.y * range;
			double z = caster.posZ + look.z * range;

			if(!spawnConstruct(world, x, y, z, null, caster, modifiers)) return false;
		}

	}else{
		return false;
	}

	this.playSound(world, caster, ticksInUse, -1, modifiers);
	return true;
}

protected boolean spawnConstruct(World world, double x, double y, double z, @Nullable EnumFacing side, @Nullable EntityLivingBase caster, SpellModifiers modifiers){

	if(!world.isRemote){
		// Creates a new construct using the supplied factory
		T construct = constructFactory.apply(world);
		// Sets the position of the construct (and initialises its bounding box)
		construct.setPosition(x, y, z);
		// Sets the various parameters
		construct.setCaster(caster);
		construct.lifetime = permanent ? -1 : (int)(getProperty(DURATION).floatValue() * modifiers.get(WizardryItems.duration_upgrade));
		construct.damageMultiplier = modifiers.get(SpellModifiers.POTENCY);
		if(construct instanceof EntityScaledConstruct) ((EntityScaledConstruct)construct).setSizeMultiplier(modifiers.get(WizardryItems.blast_upgrade));
		addConstructExtras(construct, side, caster, modifiers);
		// Prevents overlapping of multiple constructs of the same type. Since we have an instance here this is
		// very simple. The trade-off is that we have to create the entity before the spell fails, but unless
		// world.spawnEntity(...) is called, its scope is limited to this method so it should be fine.
		// Needs to be last in case addConstructExtras modifies the bounding box
		if(!allowOverlap && !world.getEntitiesWithinAABB(construct.getClass(), construct.getEntityBoundingBox()).isEmpty()) return false;
		// Spawns the construct in the world
		world.spawnEntity(construct);
	}

	return true;
}

public void onUpdate(){

	double extensionSpeed = 0;

	if(!world.isRemote){
		if(lifetime - this.ticksExisted < 15){
			extensionSpeed = -0.01 * (this.ticksExisted - (lifetime - 15));
		}else if(lifetime - this.ticksExisted < 25){
			extensionSpeed = 0;
		}else if(lifetime - this.ticksExisted < 28){
			extensionSpeed = 0.25;
		}

		if(facing != null){ // Will probably be null on the client side, but should never be on the server side
			this.move(MoverType.SELF, this.facing.getXOffset() * extensionSpeed, this.facing.getYOffset() * extensionSpeed,
					this.facing.getZOffset() * extensionSpeed);
		}
	}

	if(lifetime - this.ticksExisted == 30) this.playSound(WizardrySounds.ENTITY_ICE_SPIKE_EXTEND, 1, 2.5f);

	if(!this.world.isRemote){
		for(Object entity : this.world.getEntitiesWithinAABBExcludingEntity(this, this.getEntityBoundingBox())){
			if(entity instanceof EntityLivingBase && this.isValidTarget((EntityLivingBase)entity)){
				DamageSource source = this.getCaster() == null ? DamageSource.MAGIC : MagicDamage.causeDirectMagicDamage(this.getCaster(), DamageType.FROST);
				// Potion effect only gets added if the damage succeeded
				// We DO want knockback here or the entity gets stuck on the spike, which is a bit of a cheat
				if(((EntityLivingBase)entity).attackEntityFrom(source, Spells.ice_spikes.getProperty(Spell.DAMAGE).floatValue() * this.damageMultiplier))
					((EntityLivingBase)entity).addPotionEffect(new PotionEffect(WizardryPotions.frost,
							Spells.ice_spikes.getProperty(Spell.EFFECT_DURATION).intValue(),
							Spells.ice_spikes.getProperty(Spell.EFFECT_STRENGTH).intValue()));
			}
		}
	}

	super.onUpdate();
}

protected boolean spawnConstruct(World world, double x, double y, double z, EnumFacing side, EntityLivingBase caster, SpellModifiers modifiers){

	if(side == null) return false;

	BlockPos blockHit = new BlockPos(x, y, z);
	if(side.getAxisDirection() == EnumFacing.AxisDirection.NEGATIVE) blockHit = blockHit.offset(side);

	if(world.getBlockState(blockHit).isNormalCube()) return false;

	Vec3d origin = new Vec3d(x, y, z);

	Vec3d pos = origin.add(new Vec3d(side.getOpposite().getDirectionVec()));

	// Now always spawns a spike exactly at the position aimed at
	super.spawnConstruct(world, pos.x, pos.y, pos.z, side, caster, modifiers);
	// -1 because of the one spawned above
	int quantity = (int)(getProperty(ICE_SPIKE_COUNT).floatValue() * modifiers.get(WizardryItems.blast_upgrade)) - 1;

	float maxRadius = getProperty(EFFECT_RADIUS).floatValue() * modifiers.get(WizardryItems.blast_upgrade);

	for(int i=0; i<quantity; i++){

		double radius = 0.5 + world.rand.nextDouble() * (maxRadius - 0.5);

		// First, generate a random vector of length radius with a z component of zero
		// Then rotate it so that what was south is now the side that was hit
		Vec3d offset = Vec3d.fromPitchYaw(world.rand.nextFloat() * 180 - 90, world.rand.nextBoolean() ? 0 : 180)
				.scale(radius).rotateYaw(side.getHorizontalAngle() * (float)Math.PI/180).rotatePitch(GeometryUtils.getPitch(side) * (float)Math.PI/180);

		if(side.getAxis().isHorizontal()) offset = offset.rotateYaw((float)Math.PI/2);

		Integer surface = BlockUtils.getNearestSurface(world, new BlockPos(origin.add(offset)), side,
				(int)maxRadius, true, BlockUtils.SurfaceCriteria.basedOn(IBlockState::isNormalCube));

		if(surface != null){
			Vec3d vec = GeometryUtils.replaceComponent(origin.add(offset), side.getAxis(), surface)
					.subtract(new Vec3d(side.getDirectionVec()));
			super.spawnConstruct(world, vec.x, vec.y, vec.z, side, caster, modifiers);
		}
	}

	return true;
}

protected void addConstructExtras(EntityIceSpike construct, EnumFacing side, EntityLivingBase caster, SpellModifiers modifiers){
	// In this particular case, lifetime is implemented as a delay instead so is treated differently.
